268				continue
269			}
270			marker.Liveness, marker.Detail = probeStartLockOwner(marker.Owner)
271			marker.StalledAt = readDelegationStall(dir, marker)
272			if marker.StalledAt == "" && delegationMarkerSilent(marker, time.Now()) && marker.Liveness == LockOwnerDead {
273				marker.StalledAt = recordDelegationStall(dir, marker)
274			}
275			if _, err := os.Lstat(cancelRequestPath(dir, marker)); err == nil {
276				marker.CancelRequested = true
277			}
